# 毕业设计 Step7: 递归字符切分器
def recursive_split(text: str, chunk_size: int = 200, overlap: int = 30,
                    separators=None) -> list:
    """递归切分: 按分隔符优先级切, 超长继续降一级切, 片间保留重叠。"""
    if separators is None:
        separators = ["\n\n", "\n", "。", " ", ""]
    if len(text) <= chunk_size:
        return [text] if text.strip() else []

    # 1. 选第一个能切开 text 的分隔符(空串=按字符硬切, 保底)
    sep = separators[-1]
    for s in separators:
        if s == "" or s in text:
            sep = s
            break

    # 2. 按选定分隔符切
    parts = text.split(sep) if sep else list(text)

    # 3. 贪心合并碎片成 <= chunk_size 的块, 超长块递归降一级
    chunks, current = [], ""
    for part in parts:
        piece = part + sep if sep else part  # 把分隔符粘回去保住语义
        if len(current) + len(piece) <= chunk_size:
            current += piece
        else:
            if current.strip():
                chunks.append(current)
            # 单个 piece 就超长 → 用下一级分隔符递归
            if len(piece) > chunk_size:
                idx = separators.index(sep)
                chunks.extend(recursive_split(piece, chunk_size, overlap, separators[idx + 1:]))
                current = ""
            else:
                current = piece
    if current.strip():
        chunks.append(current)

    # 4. 相邻块加 overlap 重叠(从前一块尾部借字符)
    if overlap > 0 and len(chunks) > 1:
        overlapped = [chunks[0]]
        for i in range(1, len(chunks)):
            prev_tail = chunks[i - 1][-overlap:]
            overlapped.append(prev_tail + chunks[i])
        return overlapped
    return chunks


paper = (
    "注意力机制是 Transformer 的核心。它允许模型关注输入的不同位置。\n\n"
    "QKV 是三个可学习矩阵。查询与键做点积得到注意力分数。\n\n"
    "多头注意力把 d_model 拆成 h 个头并行。每个头学习不同的关注模式。"
)

if __name__ == "__main__":
    chunks = recursive_split(paper)
    for i, c in enumerate(chunks):
        print(f"[{i}] ({len(c)}字) {c[:30]}...")
    print(f"共 {len(chunks)} 片")

